import { sections, footerColumns, originalRepo } from './data/content.mjs';
import { assessments, byId, categories, countries, domains } from './data/assessments.mjs';
import { FILTER_DEFAULTS, normalizeParams, filterAssessments, validSelection, parseSelection, withParams } from './lib/catalog.mjs';
import { icon } from './lib/icons.mjs';
const $ = (selector, root=document)=>root.querySelector(selector);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['Home','/'],['Training','/training/'],['Testing Library','/testing-library/'],['Resources','/resources/'],['About','/about/']];
const path=location.pathname.replace(/\/+/g,'/');
const pathname=path.endsWith('/')?path:path+'/';
const isLibrary=pathname==='/testing-library/';
const isCompare=pathname==='/testing-library/compare/';
const maybeSlug=pathname.match(/^\/testing-library\/([^/]+)\/$/)?.[1];
const fromUrl=new URLSearchParams(location.search);
let filters=normalizeParams(fromUrl);
// The reference design shows three example tests selected. Clearing them is retained in the URL.
let selected=fromUrl.has('compare')?parseSelection(fromUrl.get('compare')):['ntoa-pfq','rasp','artillerijaeger'];
let searchTimeout;
const APP=$('#app');
function image(name){return `/assets/${encodeURIComponent(name)}`;}
function flag(a){return `<img class="flag" src="/assets/flags/${a.countryCode.toLowerCase()}.svg" alt="" width="24" height="16" loading="lazy"/>`;}
function reference(a){const page=a.source.label.split('—').at(-1).trim();const safe=esc(a.source.publisher);return `<p class="apa-reference">${safe}. (n.d.). <em>${esc(page)}</em>. <a href="${esc(a.source.url)}" rel="noopener noreferrer" target="_blank">${esc(a.source.url)}</a></p>`;}
function resourceTiles(list){return `<div class="resource-tiles">${list.map(([label,url,description,ico])=>`<a class="resource-tile" href="${esc(url)}"><span class="resource-tile-icon">${icon(ico||'ruck',33)}</span><strong>${esc(label)}</strong><span>${esc(description)}</span><span class="resource-tile-link">Explore ${icon('arrow',15)}</span></a>`).join('')}</div>`;}
function actionStrip(){return `<section class="wrap action-strip" aria-label="Keep progressing"><div class="action-intro"><span class="eyebrow">YOUR NEXT CHALLENGE</span><h2>BUILD. TEST. PROGRESS.</h2><p>Rucking, strength and endurance—for demanding events, selection assessments and anyone ready for more.</p></div><div class="action-links"><a href="/training/ruck-plans/">${icon('clock',26)}<span><strong>Plan & train</strong><small>Choose a goal and put the work in.</small></span></a><a href="/testing-library/">${icon('chart',26)}<span><strong>Test & compare</strong><small>See the standards and set your target.</small></span></a><a href="/resources/ruck-clubs/">${icon('layers',26)}<span><strong>Ruck together</strong><small>Find your people and raise the bar.</small></span></a></div></section>`;}
function siteHeader(){const active=pathname.startsWith('/training/')?'Training':pathname.startsWith('/resources/')?'Resources':pathname.startsWith('/testing-library/')?'Testing Library':nav.find(([label,url])=>url===pathname)?.[0]||'Home';return `
 <a class="skip-link" href="#main">Skip to content</a>
 <header class="site-header"><div class="header-inner wrap">
   <a class="brand" href="/" aria-label="Rucking Revolution home"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 56 42" width="54" height="41" fill="none"><path d="M3 38 19 8l8 15 9-20 18 35h-9L36 21l-9 19-9-17L12 38H3Z" fill="#b6262e"/><path d="m17 38 7-14 7 14h-6l-2-5-2 5h-4Z" fill="#e14a50"/></svg></span><span class="brand-text"><strong>RUCKING REVOLUTION</strong><small>PEOPLE  |  PURPOSE  |  SHARED MILES</small></span></a>
   <nav class="nav-desktop" aria-label="Main navigation">${nav.map(([text,url])=>`<a class="nav-link ${active===text?'active':''}" ${active===text?'aria-current="page"':''} href="${url}">${text}</a>`).join('')}</nav>
   <div class="header-actions"><a class="icon-button nav-search" href="/testing-library/#library-search" aria-label="Search the testing library">${icon('search',20)}</a><span class="header-divider"></span><a class="button button-primary header-join" href="/about/#community">Join the community ${icon('arrow',16)}</a><button class="icon-button mobile-toggle" type="button" aria-expanded="false" aria-controls="mobile-nav" aria-label="Open menu">${icon('menu',24)}</button></div>
 </div><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation" hidden>${nav.map(([text,url])=>`<a class="${active===text?'active':''}" href="${url}">${text}</a>`).join('')}<a href="/about/#community">Join the community</a></nav></header>`;}
function siteFooter(){return `<footer class="site-footer" id="footer"><div class="wrap footer-top"><section class="footer-brand"><a class="footer-wordmark" href="/">${icon('ruck',30)} <strong>RUCKING REVOLUTION</strong></a><p>A civilian rucking platform for training, testing and progress. For people who choose to do more.</p><a class="footer-contact" href="mailto:info@ruckingrevolution.org">Contact us ${icon('arrow',15)}</a></section>${footerColumns.map(column=>`<nav aria-label="${esc(column.title)} links" class="footer-column"><h2>${esc(column.title)}</h2>${column.items.map(([name,url])=>`<a href="${esc(url)}" ${url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${esc(name)}</a>`).join('')}</nav>`).join('')}</div><div class="wrap footer-bottom"><span>© 2026 Rucking Revolution · Built for people who want more from the miles.</span><nav aria-label="Legal and sources"><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a><a href="/credits/">Credits</a><a href="/references/">References</a></nav></div></footer>`;}
function layout(content,{className='',hero=false}={}){APP.innerHTML=`${siteHeader()}<main id="main" tabindex="-1" class="${className}">${content}</main>${siteFooter()}`;$('.mobile-toggle')?.addEventListener('click',e=>{let b=e.currentTarget,m=$('#mobile-nav');let open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));b.setAttribute('aria-label',open?'Open menu':'Close menu');m.hidden=open;});document.title=(document.querySelector('h1')?.textContent||'Rucking Revolution')+' | Rucking Revolution';}
function sectionEyebrow(t){return `<span class="eyebrow">${esc(t)}</span>`;}
function libraryHero(){return `<section class="library-intro wrap"><div class="intro-center">${sectionEyebrow('REAL TESTS. HIGHER STANDARDS.')}<h1>TESTING LIBRARY</h1><p>Explore and compare fitness tests from around the world—for demanding events, selection assessments and your next goal.</p><form role="search" id="library-search" class="search-box" novalidate><label class="sr-only" for="test-search">Search tests, countries or activities</label>${icon('search',21)}<input id="test-search" type="search" autocomplete="off" maxlength="120" placeholder="Search tests, countries, or activities…" value="${esc(filters.q)}"/><button type="submit" aria-label="Search">${icon('arrow',18)}</button></form></div>
<nav class="category-row" aria-label="Types of fitness tests">${categories.map(c=>`<button type="button" data-category="${esc(c.id)}" class="category-pill ${filters.category===c.id?'active':''}" aria-pressed="${filters.category===c.id}">${icon(c.icon,19)}<span>${esc(c.label)}</span></button>`).join('')}</nav></section>`;}
function options(values,allLabel,chosen){return `<option value="all">${esc(allLabel)}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===chosen?'selected':''}>${esc(v)}</option>`).join('');}
function filterControl(name,label,svg,html){return `<label class="filter-control"><span class="filter-icon">${icon(svg,19)}</span><span class="filter-copy"><span>${esc(label)}</span><select id="filter-${esc(name)}" data-filter="${esc(name)}" aria-label="${esc(label)}">${html}</select></span>${icon('down',15)}</label>`;}
function filterBar(){return `<section class="filters-panel wrap" aria-label="Narrow the results"><div class="filters-main">
${filterControl('country','Country','globe',options(countries,'All countries',filters.country))}
${filterControl('domain','Type','layers',options(domains,'All types',filters.domain))}
${filterControl('scoring','Scoring','chart',options(['Graded','Pass / fail','Points'],'All scoring',filters.scoring))}
${filterControl('reproducibility','Instructions','refresh',options([...new Set(assessments.map(a=>a.reproducibility))].sort(),'All instructions',filters.reproducibility))}
${filterControl('status','Sources','tag',options(['Official source'],'All tests',filters.status))}
</div><div class="filters-end"><button type="button" id="clear-filters" class="text-button">Clear filters</button><span class="filter-separator"></span>${filterControl('sort','Sort by','sort',[['relevance','Relevance'],['name','Name'],['country','Country']].map(([v,l])=>`<option value=\"${v}\" ${filters.sort===v?'selected':''}>${l}</option>`).join(''))}</div></section>`;}
function testCard(a){const checked=selected.includes(a.id);return `<article class="test-card" data-id="${a.id}"><div class="card-photo photo-${a.id}"><div class="card-topline"><label class="compare-check"><input type="checkbox" data-select="${a.id}" ${checked?'checked':''} aria-label="Compare ${esc(a.shortName)}"/><span>Compare</span></label><span class="type-badge">${esc(a.kind)}</span></div><div class="card-title"><h3><a href="/testing-library/${a.id}/">${esc(a.shortName)}</a></h3><p>${esc(a.subtitle)}</p><div class="card-meta"><span>${flag(a)}</span><span>${esc(a.country)}</span><span class="meta-divider" aria-hidden="true"></span><span>${esc(a.domain)}</span></div></div></div><div class="card-bottom"><div class="metric"><span class="metric-label">KEY ACTIVITY</span><div class="metric-row">${icon(a.metric.icon,24)}<span><strong>${esc(a.metric.label)}</strong><small>${esc(a.metric.detail)}</small></span></div></div><div class="card-tags">${a.tags.slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</div></div></article>`;}
function libraryResults(){const result=filterAssessments(assessments,filters);return `<section class="results wrap" aria-label="Testing library results"><div class="results-heading"><div><strong id="result-count" aria-live="polite">${result.length} ${result.length===1?'test':'tests'}</strong><span class="results-summary">${result.length===assessments.length?'Published fitness tests for people working toward their next challenge.':'Matching your search and filters.'}</span></div><div class="view-switch" role="group" aria-label="Choose result layout"><button type="button" data-view="grid" aria-pressed="${filters.view==='grid'}" class="${filters.view==='grid'?'active':''}">${icon('grid',16)} Grid</button><button type="button" data-view="list" aria-pressed="${filters.view==='list'}" class="${filters.view==='list'?'active':''}">${icon('list',17)} List</button></div></div>
<div id="card-grid" class="cards ${filters.view==='list'?'list-view':''}">${result.map(testCard).join('')||`<div class="empty-state"><h2>No matches this time</h2><p>Try another search, or clear the filters to see every test.</p><button type="button" id="empty-clear" class="button button-secondary">Show all tests</button></div>`}</div></section>`;}
function compareTray(){if(!selected.length)return `<div id="compare-tray" class="compare-tray wrap" hidden></div>`;return `<aside class="compare-tray wrap" id="compare-tray" aria-label="Selected tests for comparison"><div class="tray-copy"><span class="tray-icon">${icon('layers',30)}</span><span><strong>${selected.length} ${selected.length===1?'test':'tests'} selected</strong><small>Compare up to three, side by side</small></span></div><div class="tray-items">${selected.map(id=>{const a=byId[id];return `<div class="tray-item"><span class="tray-flag">${flag(a)}</span><span><strong>${esc(a.shortName)}</strong><small>${esc(a.country)}</small></span><button type="button" class="tray-remove" data-remove="${id}" aria-label="Remove ${esc(a.shortName)}">${icon('close',18)}</button></div>`}).join('')}</div><div class="tray-actions"><button class="text-button tray-clear" type="button" id="clear-comparison">Clear</button><a class="button button-primary tray-submit ${selected.length<2?'disabled':''}" ${selected.length<2?'aria-disabled="true" tabindex="-1"':''} href="${selected.length>=2?'/testing-library/compare/?ids='+encodeURIComponent(selected.join(',')):'#'}">Compare ${selected.length} ${selected.length===1?'test':'tests'} ${icon('arrow',18)}</a></div></aside>`;}
function library(){layout(`${libraryHero()}${filterBar()}${libraryResults()}${actionStrip()}<div id="tray-root">${compareTray()}</div>`,{className:'library-page'});bindLibrary();if(location.hash==='#library-search')$('#test-search')?.focus();}
function replaceFilters(){const p=new URLSearchParams();for(const [key,v] of Object.entries(filters)){if(v!==FILTER_DEFAULTS[key]&&v!==''&&v!==null)p.set(key,v)}p.set('compare',selected.join(',')||'none');history.replaceState({},'',location.pathname+'?'+p.toString());}
function updateView(){const res=$('.results');if(res){const holder=document.createElement('div');holder.innerHTML=libraryResults();res.replaceWith(holder.firstElementChild);}const root=$('#tray-root');if(root)root.innerHTML=compareTray();$('.category-row').innerHTML=categories.map(c=>`<button type="button" data-category="${esc(c.id)}" class="category-pill ${filters.category===c.id?'active':''}" aria-pressed="${filters.category===c.id}">${icon(c.icon,19)}<span>${esc(c.label)}</span></button>`).join('');for(const [key,v] of Object.entries(filters)){const select=$(`[data-filter="${key}"]`);if(select)select.value=v;}replaceFilters();}
function bindLibrary(){
  $('#library-search').addEventListener('submit',e=>{e.preventDefault();clearTimeout(searchTimeout);filters.q=$('#test-search').value;updateView();});
  $('#test-search').addEventListener('input',e=>{const q=e.target.value;clearTimeout(searchTimeout);searchTimeout=setTimeout(()=>{filters.q=q;updateView();},180);});
  $('#main').addEventListener('click',e=>{
    const category=e.target.closest('[data-category]');if(category){filters.category=category.dataset.category;updateView();return;}
    const view=e.target.closest('[data-view]');if(view){filters.view=view.dataset.view;updateView();return;}
    const remove=e.target.closest('[data-remove]');if(remove){selected=selected.filter(id=>id!==remove.dataset.remove);updateView();return;}
    if(e.target.closest('#clear-comparison')){selected=[];updateView();return;}
    if(e.target.closest('#clear-filters,#empty-clear')){filters={...FILTER_DEFAULTS};$('#test-search').value='';updateView();return;}
  });
  $('#main').addEventListener('change',e=>{
    const select=e.target.closest('select[data-filter]');if(select){filters[select.dataset.filter]=select.value;updateView();return;}
    const checkbox=e.target.closest('input[data-select]');if(!checkbox)return;
    if(checkbox.checked){if(selected.length>=3){checkbox.checked=false;announce('You can compare up to three tests. Remove one first.');return;}selected=validSelection([...selected,checkbox.dataset.select]);}
    else selected=selected.filter(id=>id!==checkbox.dataset.select);
    updateView();
  });
  $('#main').addEventListener('keydown',e=>{if(e.key==='Escape'&&e.target=== $('#test-search')){e.target.value='';filters.q='';updateView();}});
}
function announce(message){let live=$('#notice-live');if(!live){live=document.createElement('p');live.className='sr-only';live.id='notice-live';live.setAttribute('role','status');document.body.append(live);}live.textContent=message;}
function crumbs(pairs){return `<nav class="breadcrumbs" aria-label="Breadcrumb">${pairs.map(([name,href],i)=>i===pairs.length-1?`<span aria-current="page">${esc(name)}</span>`:`<a href="${href}">${esc(name)}</a><span aria-hidden="true">/</span>`).join('')}</nav>`;}
function detail(a){if(!a){notFound();return;}layout(`<div class="wrap inner-page">${crumbs([['Testing Library','/testing-library/'],[a.shortName,'']])}<div class="detail-hero photo-${a.id}"><div>${sectionEyebrow(`${a.country} · ${a.domain}`)}<h1>${esc(a.shortName)}</h1><p class="detail-subtitle">${esc(a.name)}</p><span class="type-badge static-badge">${esc(a.kind)}</span></div></div><div class="detail-grid"><div><section class="content-panel"><h2>At a glance</h2><p>${esc(a.overview)}</p><div class="activity-highlight">${icon(a.metric.icon,27)}<div><span>FEATURED ACTIVITY</span><strong>${esc(a.metric.label)}</strong><small>${esc(a.metric.detail)}</small></div></div></section><section class="content-panel"><h2>What the test includes</h2><ul class="detail-list">${a.components.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="footnote">Some programmes include more than the activities listed here.</p></section></div><aside><section class="content-panel source-panel"><h2>Read the original details</h2><p>The organisation running the test is the best place to check the latest rules and requirements.</p><a class="button button-primary full" href="${esc(a.source.url)}" target="_blank" rel="noopener noreferrer">Visit ${esc(a.source.publisher)} ${icon('external',17)}</a>${(a.otherSources||[]).map(x=>`<a class="source-extra" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.label)} ${icon('external',16)}</a>`).join('')}<div class="reference-note"><span class="eyebrow">REFERENCE</span>${reference(a)}</div></section><section class="content-panel"><h2>Worth knowing</h2><ul class="simple-list">${a.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></section><a class="button button-secondary full" href="/testing-library/">${icon('back',18)} Back to all tests</a></aside></div></div>`,{className:'subpage'});}
function compare(){const ids=parseSelection(fromUrl.get('ids')||fromUrl.get('compare'));const tests=ids.map(id=>byId[id]);if(!tests.length){layout(`<div class="wrap inner-page">${crumbs([['Testing Library','/testing-library/'],['Compare','']])}<h1>Compare tests</h1><p>Select two or three tests to see their activities and requirements side by side.</p><a class="button button-primary" href="/testing-library/">Choose tests ${icon('arrow',17)}</a></div>`);return;}const headings=tests.map(t=>`<th scope="col"><img src="${image(t.image)}" alt=""/><span>${flag(t)} ${esc(t.shortName)}</span><small>${esc(t.country)}</small></th>`).join('');const row=(title,fn)=>`<tr><th scope="row">${esc(title)}</th>${tests.map(t=>`<td>${fn(t)}</td>`).join('')}</tr>`;layout(`<div class="wrap inner-page compare-page">${crumbs([['Testing Library','/testing-library/'],['Compare','']])}${sectionEyebrow('SIDE BY SIDE')}<h1>Compare fitness tests</h1><p class="page-lead">See what each test asks for. They come from different organisations, so the scores aren't directly interchangeable.</p><div class="compare-tools"><a href="/testing-library/?compare=${encodeURIComponent(ids.join(','))}" class="button button-secondary">${icon('back',16)} Change selection</a><button type="button" class="button button-ghost" id="copy-compare">${icon('layers',17)} Copy a link</button></div><div class="table-scroll" tabindex="0" role="region" aria-label="Test comparison table"><table class="compare-table"><thead><tr><th scope="col">Test details</th>${headings}</tr></thead><tbody>${row('Type',t=>esc(t.kind.toLowerCase()))}${row('Organisation',t=>esc(t.source.publisher))}${row('Country',t=>esc(t.country))}${row('Scoring',t=>esc(t.scoring))}${row('Featured activity',t=>`<strong>${esc(t.metric.label)}</strong><small>${esc(t.metric.detail)}</small>`)}${row('Activities',t=>`<ul>${t.components.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`)}${row('Original source',t=>`<a target="_blank" rel="noopener noreferrer" href="${esc(t.source.url)}">Open details ${icon('external',14)}</a>`)}</tbody></table></div><p class="footnote">The official website for each test has the full instructions and any updated entry requirements.</p><section class="comparison-references" aria-label="Source references"><h2>References</h2>${tests.map(reference).join('')}</section></div>`,{className:'subpage'});$('#copy-compare')?.addEventListener('click',async e=>{try{await navigator.clipboard.writeText(location.href);e.currentTarget.textContent='Link copied';}catch{e.currentTarget.textContent='Copy the address from your browser';}});}
const shortCards=(items)=>`<div class="feature-grid">${items.map(({icon:i,eyebrow,title,body,href,action})=>`<article class="feature-card">${icon(i,27)}<span class="eyebrow">${esc(eyebrow)}</span><h3>${esc(title)}</h3><p>${esc(body)}</p><a href="${esc(href)}">${esc(action||'Explore')} ${icon('arrow',16)}</a></article>`).join('')}</div>`;
function home(){layout(`<div class="wrap home-hero"><div class="home-hero-text">${sectionEyebrow('PEOPLE · PURPOSE · HIGHER STANDARDS')}<h1>RUCK WITH<br/><em>PURPOSE.</em></h1><p>Go further, carry more, get stronger. Whether you're training for a selection, a demanding event, or a challenge you set yourself, the work starts with your next ruck.</p><div class="hero-actions"><a href="/training/ruck-plans/" class="button button-primary">Build your training ${icon('arrow',18)}</a><a href="/testing-library/" class="button button-secondary">Explore fitness tests</a></div></div><div class="hero-fact"><span>01 / SET YOUR NEXT TARGET</span><strong>Distance.<br/>Load.<br/>Pace.<br/>Progress.</strong></div></div><section class="wrap home-section">${sectionEyebrow('WORK TOWARD SOMETHING')}<h2>Make every ruck count.</h2>${shortCards([{icon:'ruck',eyebrow:'DO THE WORK',title:'Train with direction',body:'Structured rucks, hills, strength sessions and longer efforts—build toward a goal instead of collecting random miles.',href:'/training/ruck-plans/',action:'Build a plan'},{icon:'chart',eyebrow:'KNOW THE STANDARD',title:'Test yourself',body:'Understand published fitness assessments, find what you need to improve and compare tests side by side.',href:'/testing-library/',action:'Browse tests'},{icon:'layers',eyebrow:'TAKE IT FURTHER',title:'Get out there',body:'Explore route ideas, event preparation, field notes and ways to build a rucking crew.',href:'/resources/',action:'Explore resources'}])}</section><section class="wrap progress-banner"><div><span class="eyebrow">MORE THAN JUST DISTANCE</span><h2>PUT THE WORK IN.<br/>SEE WHAT CHANGES.</h2><p>Pick a route. Set a benchmark. Take on the hill you avoided last time. Track what improves and carry that progress into your next challenge.</p><a class="button button-primary" href="/training/workouts/">Find a session ${icon('arrow',16)}</a></div></section><section class="wrap callout-row" id="community"><div>${sectionEyebrow('BETTER TOGETHER')}<h2>You don’t need to do it alone.</h2><p>A hard ruck is easier to commit to when people show up, share the effort and push each other to finish stronger.</p></div><a class="button button-primary" href="/about/#community">Find your people ${icon('arrow',16)}</a></section>`,{className:'home-page'});}
function training(){layout(`<div class="wrap inner-page">${sectionEyebrow('TRAIN FOR YOUR NEXT CHALLENGE')}<h1>Training</h1><p class="page-lead">Build the endurance, strength and confidence to take on longer rucks, harder terrain, high-intensity events or a formal assessment. Choose what you are working toward, then put structure behind it.</p>${resourceTiles([['Rucking plans','/training/ruck-plans/','Build consistency, distance and load over time.','ruck'],['Workouts','/training/workouts/','Hills, urban sessions, teamwork and purposeful effort.','barbell'],['Assessment prep','/training/assessment-prep/','Work backwards from the actual test requirements.','chevrons'],['Strength & conditioning','/training/strength/','Build the strength that supports harder rucks.','run']])}<section class="session-builder content-panel" id="training-week"><div><span class="eyebrow">PRACTICAL STARTING POINT</span><h2>Build your next training week</h2><p>Choose what you’re aiming for. This gives you a starting structure you can adjust around your current ability and the actual demands of your goal.</p></div><form id="week-builder" class="week-controls"><label>My goal<select id="week-goal"><option value="distance">Long-distance event</option><option value="selection">Fitness assessment or selection</option><option value="intensity">Harder, faster rucks</option><option value="community">Group challenge</option></select></label><label>My current level<select id="week-level"><option value="building">Building consistency</option><option value="regular">Rucking regularly</option><option value="experienced">Experienced with longer efforts</option></select></label><button class="button button-primary" type="submit">Build the week ${icon('arrow',16)}</button></form><div id="week-result" class="week-result" aria-live="polite"><p>Pick your goal and level, then build your week.</p></div></section>${actionStrip()}</div>`,{className:'subpage'});$('#week-builder')?.addEventListener('submit',e=>{e.preventDefault();const goal=$('#week-goal').value,level=$('#week-level').value;const sessions={distance:['A steady midweek ruck with a repeatable pace','A longer ruck on terrain similar to your event','Strength, foot care and an easier recovery day'],selection:['A benchmark practice session for one published test component','A focused ruck, run or strength workout addressing a weak area','A longer mixed session followed by planned recovery'],intensity:['A controlled hill or stair interval ruck','A steady ruck for pacing and efficiency','A challenging sustained effort with adequate recovery'],community:['One personal ruck at your own level','A planned group ruck with a shared route and clear regroup points','A hill, load or timed challenge with adaptable options']};const scaling={building:'Keep the volume comfortable enough to repeat next week. Start without added weight if needed.',regular:'Keep the quality high and increase only one variable at a time.',experienced:'Add challenge through terrain, pace or duration while protecting recovery.'};$('#week-result').innerHTML=`<h3>Your three key sessions</h3><ol>${sessions[goal].map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p>${esc(scaling[level])}</p><small>Example structure only; adapt it to your capacity and follow official test requirements where relevant.</small>`;});}
function resources(){layout(`<div class="wrap inner-page">${sectionEyebrow('WORK, LEARN, REPEAT')}<h1>Resources</h1><p class="page-lead">Routes to plan, workouts to try, things to learn and events worth training for. Curated from the original Rucking Revolution project and adapted for v2.</p>${resourceTiles([['Articles','/resources/articles/','Rucking form, nutrition, endurance and real-world progress.','layers'],['Field notes','/resources/field-notes/','Learn from tough conditions and shared rucks.','compare'],['Rucking routes','/resources/routes/','City loops, ridgelines and longer-route planning.','ruck'],['Events & challenges','/resources/events/','Prepare for hard events and demanding distances.','chevrons'],['Recommended reading','/resources/reading/','Books that help you go further or think differently.','layers'],['Start a ruck crew','/resources/ruck-clubs/','Build a group worth showing up for.','globe'],['Tools & templates','/resources/tools/','Checklists and session logs you can put to work.','grid']])}<section class="content-panel resource-note"><h2>Looking for a particular assessment?</h2><p>Our testing library links directly to the organisations publishing the rules, with the activities laid out in plain English.</p><a class="button button-primary" href="/testing-library/">Open Testing Library ${icon('arrow',17)}</a></section></div>`,{className:'subpage'});}
function about(){layout(`<div class="wrap inner-page">${sectionEyebrow('ABOUT RUCKING REVOLUTION')}<h1>People. Purpose. Higher standards.</h1><p class="page-lead">Rucking is simple to start, but there’s no need to keep it easy. This is a place for people who want to get stronger, cover hard miles, prepare for something that matters and bring others along.</p><div class="reading-grid"><section class="content-panel"><h2>What we are here for</h2><p>We bring practical training ideas, real assessment requirements and useful lessons from people who ruck. Some are working toward competitive events or demanding selections. Others want an ambitious challenge outside work. All are welcome to train with purpose.</p></section><section class="content-panel"><h2>Everyone gets to choose their challenge</h2><p>Higher standards do not mean everyone has to carry the same weight or hold the same pace. Bring a serious attitude, choose a goal that means something to you and do the work to reach it.</p></section><section class="content-panel"><h2>From the original project</h2><p>The original Rucking Revolution includes articles, training workouts, rucking routes, field notes and community leadership material. V2 keeps that ambition while making the library easier to explore and use.</p><a class="plain-source" href="${originalRepo}" target="_blank" rel="noopener noreferrer">Original repository ${icon('external',16)}</a></section><section class="content-panel"><h2>Independent by design</h2><p>V2 presents publicly available assessment information in a clearer format. The organisations listed in the Testing Library set their own rules and are not connected with or endorsing this site.</p></section></div><section class="callout-row" id="community"><div>${sectionEyebrow('BETTER TOGETHER')}<h2>You don’t need to do it alone.</h2><p>Show up for a shared ruck, take on something demanding and find people who make you want to come back stronger.</p></div><a class="button button-primary" href="mailto:info@ruckingrevolution.org?subject=Rucking%20together">Find your people ${icon('arrow',16)}</a></section></div>`,{className:'subpage'});}
function contentPage(data){layout(`<div class="wrap inner-page content-route">${crumbs([[location.pathname.startsWith('/training/')?'Training':'Resources',location.pathname.startsWith('/training/')?'/training/':'/resources/'],[data.title,'']])}${sectionEyebrow(data.eyebrow)}<h1>${esc(data.title)}</h1><p class="page-lead">${esc(data.lead)}</p><div class="article-content-grid">${data.blocks.map((b,i)=>`<section class="content-panel article-section"><span class="article-count">${String(i+1).padStart(2,'0')}</span><h2>${esc(b.title)}</h2>${b.text?`<p>${esc(b.text)}</p>`:''}${b.items?.length?`<ul class="detail-list">${b.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}</section>`).join('')}</div><aside class="content-source"><p>Adapted from the original Rucking Revolution ${esc(data.sourceLabel.toLowerCase())}. Event and route information is offered as a planning example, not a current listing.</p><a href="${esc(data.source)}" target="_blank" rel="noopener noreferrer">View the original material ${icon('external',15)}</a></aside><div class="route-more"><a class="button button-secondary" href="${location.pathname.startsWith('/training/')?'/training/':'/resources/'}">${icon('back',17)} Back to ${location.pathname.startsWith('/training/')?'training':'resources'}</a><a class="button button-primary" href="/testing-library/">Explore fitness tests ${icon('arrow',17)}</a></div></div>`,{className:'subpage'});}
function legalPage(type){const map={privacy:{title:'Privacy',lead:'The current v2 website is a static resource with no accounts, tracking scripts or newsletter database.',blocks:[['What this site uses','The site uses local images and JavaScript to show the library, remember selections in the page address and help you compare tests.'],['When you contact us','If you use an email link, your email provider and the recipient handle that message under their own privacy terms.'],['External links','Official publishers, social platforms and other outside websites have their own privacy policies.']]},terms:{title:'Terms',lead:'Information here is for learning and planning. It is not an official entry guide for any particular organisation or event.',blocks:[['Test standards','Always check the current published requirements from the organisation running the assessment.'],['Training responsibility','Choose a workload appropriate for your own situation, equipment and environment.'],['Brand and material','Rucking Revolution is presented here as an independent v2 redevelopment of its original site.']]},credits:{title:'Credits',lead:'Rucking Revolution v2 was built around the owner-supplied interface references and the original project’s content structure.',blocks:[['Imagery and icons','Editorial illustrations and photographic-style images created for this v2. They do not depict particular official tests.'],['Original project',`Rucking Revolution’s original ${originalRepo} supplied themes, content categories and footer information.`],['Assessment information','Official publishers are linked from each test detail and the references page.']]}};const d=map[type];layout(`<div class="wrap inner-page"><h1>${d.title}</h1><p class="page-lead">${esc(d.lead)}</p><div class="reading-grid">${d.blocks.map(([h,p])=>`<section class="content-panel"><h2>${esc(h)}</h2><p>${esc(p)}</p></section>`).join('')}</div></div>`,{className:'subpage'});}
function referencePage(){layout(`<div class="wrap inner-page"><span class="eyebrow">PUBLISHED TEST INFORMATION</span><h1>References</h1><p class="page-lead">For exact assessment rules, dates and scoring, the original publishers are the source to use. These references use APA-style formatting.</p><div class="content-panel">${assessments.map(a=>`<div class="bibliography-item"><strong>${esc(a.shortName)}</strong>${reference(a)}</div>`).join('')}<p class="footnote">Access checked on 24 November 2026. Official pages may change without notice.</p></div></div>`,{className:'subpage'});}
function notFound(){layout(`<div class="wrap inner-page"><h1>We couldn't find that page</h1><p>It may have moved, or the address might have a typo.</p><a class="button button-primary" href="/testing-library/">Back to the testing library ${icon('arrow',16)}</a></div>`);}
if(isLibrary)library();else if(isCompare)compare();else if(maybeSlug)detail(byId[maybeSlug]);else if(pathname==='/')home();else if(pathname==='/training/')training();else if(pathname==='/resources/')resources();else if(pathname==='/about/')about();else if(sections[pathname])contentPage(sections[pathname]);else if(pathname==='/references/')referencePage();else if(['/privacy/','/terms/','/credits/'].includes(pathname))legalPage(pathname.split('/')[1]);else notFound();
